// Power Electronics — Lecture 4: DC-DC converters. Ported from docs/superpowers/pe1-artifact.html.

// Same colour for the same quantity in every derive block of this module. Slot 8 is left free for
// one-off helper tags (numbers, brackets); on/off heights borrow the slots of quantities absent from that block.
const COL = { Vs: 1, Vo: 2, D: 3, omd: 4, Ts: 5, IL: 6, Io: 7 };
const COLV = { ...COL, on: 6, off: 7 };          // voltage blocks: no I_L / I_o in them
const COLI = { ...COL, on: 1, off: 2 };          // current blocks: no V_s / V_o in them
const COLR = { ...COL, vL: 6, L: 7 };            // ripple blocks

